css:
@font-face { font-family: 'Hand'; font-weight: 700; src: url(node_modules/@fontsource/caveat/files/caveat-latin-700-normal.woff2); }
@font-face { font-family: 'Lex'; font-weight: 400; src: url(node_modules/@fontsource/lexend/files/lexend-latin-400-normal.woff2); }
@font-face { font-family: 'Lex'; font-weight: 500; src: url(node_modules/@fontsource/lexend/files/lexend-latin-500-normal.woff2); }
@font-face { font-family: 'Lex'; font-weight: 700; src: url(node_modules/@fontsource/lexend/files/lexend-latin-700-normal.woff2); }
@font-face { font-family: 'Lex'; font-weight: 800; src: url(node_modules/@fontsource/lexend/files/lexend-latin-800-normal.woff2); }
.card { background-color: #FBF8EE; color: #22262B; font-family: 'Lex';
  background-image: linear-gradient(#C9DCEB 2px, transparent 2px), linear-gradient(90deg, #C9DCEB 2px, transparent 2px);
  background-size: 60px 60px; }
.card::before { content: ''; position: absolute; left: 70px; top: 0; bottom: 0; width: 5px; background: #E0565B; }
.safe { padding-left: 120px !important; }
.page { font: 700 54px 'Hand'; color: #E0565B; margin: 0 0 18px; }
h1 { font: 700 150px/0.95 'Hand'; margin: 0 0 30px; color: #22262B; }
h2 { font: 700 118px/1 'Hand'; margin: 0 0 26px; color: #22262B; }
.hl { background: linear-gradient(transparent 52%, #FFE94D 52%, #FFE94D 92%, transparent 92%); padding: 0 8px; }
.hg { background: linear-gradient(transparent 52%, #9EF0B4 52%, #9EF0B4 92%, transparent 92%); padding: 0 8px; }
.hp { background: linear-gradient(transparent 52%, #FFB3CF 52%, #FFB3CF 92%, transparent 92%); padding: 0 8px; }
p { font: 500 56px/1.3 'Lex'; margin: 0 0 30px; max-width: 790px; }
.note { background: #FFFFFF; border: 5px solid #22262B; box-shadow: 12px 12px 0 #22262B; padding: 34px 40px; margin: 0 0 44px; max-width: 760px; }
.note p { margin: 0; }
.note b { font-weight: 800; }
.tag { display: inline-block; font: 800 38px 'Lex'; color: #fff; background: #E0565B; padding: 10px 22px; margin: 0 0 28px; transform: rotate(-2deg); align-self: flex-start; }
.big { white-space: nowrap; font: 800 172px/0.9 'Lex'; margin: 0 0 20px; color: #22262B; letter-spacing: -6px; }
.arrow { font: 700 80px 'Hand'; color: #E0565B; margin: 0 0 10px; }
.hook { justify-content: center; }
.hook h1 { font-size: 172px; }
.end h1 { font-size: 140px; }
.handle { font: 800 56px 'Lex'; margin-top: 30px; }
